package io.github.jackotom.hongguo.android;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.json.*;

/** Real LibraryStore and owned temporary files; only Android DownloadManager boundary is injected. */
public final class DownloadDeletionTest {
    private static int checks,passed,failed;
    private interface Checked{void run()throws Exception;}
    private static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void rejects(Checked action,String message)throws Exception{try{action.run();}catch(Exception expected){checks++;return;}throw new AssertionError(message);}
    private static void group(String name,Checked test){try{test.run();passed++;System.out.println("PASS "+name);}catch(Throwable error){failed++;System.out.println("FAIL "+name+": "+error);error.printStackTrace(System.out);}}
    private static JSONObject series()throws Exception{return new JSONObject().put("seriesId","7693823855940357144").put("title","generated fixture");}
    private static JSONObject episode(int index)throws Exception{return new JSONObject().put("vid","10000"+index).put("index",index);}
    private static JSONObject params(long id)throws Exception{return new JSONObject().put("id",id).put("confirmed",true);}
    private static String uuid(int index){return "7693823855940357144_"+index+"_12345678-1234-4234-8234-123456789abc.mp4";}
    private static String managed(int index){return "7693823855940357144_"+index+"_1700000000000.mp4";}
    private static void cleanup(File file)throws Exception{if(file.isDirectory()&&!Files.isSymbolicLink(file.toPath()))for(File child:Objects.requireNonNull(file.listFiles()))cleanup(child);Files.deleteIfExists(file.toPath());}
    private static final class Provider implements DownloadDeletion.Provider {
        final Map<Long,DownloadDeletion.Record> rows=new HashMap<>();int removes,queries;boolean failQuery,failRemove,keep;Runnable onRemove;
        public DownloadDeletion.Record query(long id)throws Exception{queries++;if(failQuery)throw new IOException("fixture provider query failed");return rows.get(id);}
        public int remove(long id)throws Exception{removes++;if(failRemove)throw new IOException("fixture provider remove failed");if(keep)return 0;boolean found=rows.remove(id)!=null;if(onRemove!=null)onRemove.run();return found?1:0;}
    }
    private static final class Fixture implements AutoCloseable {
        final File root=Files.createTempDirectory("hongguo-delete-test-").toFile(),directory=new File(root,"Download");
        final SearchHistoryStoreTest.AppContext context=new SearchHistoryStoreTest.AppContext();final LibraryStore store=new LibraryStore(context);final Provider provider=new Provider();
        Fixture()throws Exception{check(directory.mkdir(),"create temporary owned directory");context.prefs().edit().putString("history","[{\"keep\":true}]").putString("favorites","[{\"keep\":true}]").putString("search_keywords_v1","[\"keep\"]").commit();}
        File file(String name)throws Exception{File f=new File(directory,name);Files.write(f.toPath(),new byte[]{1,2,3});return f;}
        void row(long id,int index,String key,String name)throws Exception{store.addDownload(id,series(),episode(index));if(key!=null){JSONArray rows=store.downloads();rows.getJSONObject(0).put(key,name);if(key.equals("preparedFile"))rows.getJSONObject(0).put("preparedBytes",40);context.prefs().edit().putString("downloads",rows.toString()).commit();}}
        void provider(long id,File file){provider.rows.put(id,new DownloadDeletion.Record(file==null?null:file.toURI().toString(),"红果 · 视频下载"));}
        JSONObject delete(long id)throws Exception{return DownloadDeletion.delete(store,directory,provider,params(id));}
        void preserved(){check("[{\"keep\":true}]".equals(context.prefs().getString("history","")),"history preserved");check("[{\"keep\":true}]".equals(context.prefs().getString("favorites","")),"favorites preserved");check("[\"keep\"]".equals(context.prefs().getString("search_keywords_v1","")),"search preserved");}
        public void close()throws Exception{cleanup(root);}
    }
    public static void main(String[]args)throws Exception{
        group("strict confirmed boolean and safe numeric id",()->{try(Fixture f=new Fixture()){
            f.row(1,1,null,null);f.provider(1,null);String before=f.store.downloads().toString();
            for(Object raw:new Object[]{"1",0,-1,1.5,Double.NaN,Double.POSITIVE_INFINITY,9007199254740992d,JSONObject.NULL})rejects(()->DownloadDeletion.delete(f.store,f.directory,f.provider,new JSONObject().put("id",raw).put("confirmed",true)),"invalid id accepted");
            for(Object confirmed:new Object[]{false,"true",1,JSONObject.NULL})rejects(()->DownloadDeletion.delete(f.store,f.directory,f.provider,new JSONObject().put("id",1).put("confirmed",confirmed)),"unconfirmed delete accepted");
            rejects(()->DownloadDeletion.delete(f.store,f.directory,f.provider,new JSONObject().put("id",1)),"missing confirmation accepted");
            check(before.equals(f.store.downloads().toString())&&f.provider.queries==0&&f.provider.removes==0,"invalid params have no side effects");
            check(DownloadDeletion.confirmedId(params(9007199254740991L))==9007199254740991L,"maximum JS-safe id accepted");
        }});
        group("unknown local id never queries or removes provider",()->{try(Fixture f=new Fixture()){f.provider(77,null);rejects(()->f.delete(77),"unknown local id accepted");check(f.provider.queries==0&&f.provider.removes==0,"unknown id untouched");}});
        group("pending running paused jobs cancel by exact local id",()->{for(int status:new int[]{1,2,4})try(Fixture f=new Fixture()){f.row(status,1,null,null);f.provider.rows.put((long)status,new DownloadDeletion.Record(status,null,"红果 · 视频下载"));check(f.delete(status).getBoolean("deleted"),"active job deleted");check(f.provider.removes==1&&f.provider.rows.isEmpty()&&f.store.download(status)==null,"active provider and local row removed");f.preserved();}});
        group("failed system download cleans exact local record",()->{try(Fixture f=new Fixture()){f.row(16,1,null,null);f.provider.rows.put(16L,new DownloadDeletion.Record(16,null,"红果 · 视频下载"));f.delete(16);check(f.provider.rows.isEmpty()&&f.store.download(16)==null,"failed provider row removed");}});
        group("completed normal DM file and metadata removed",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1)),other=f.file(managed(2));f.row(1,1,null,null);f.provider(1,target);JSONObject result=f.delete(1);check(result.getLong("id")==1&&result.getBoolean("deleted"),"exact result");check(!target.exists()&&other.exists()&&f.store.download(1)==null,"only target file and row removed");f.preserved();}});
        group("new web downloads persist exact destination mapping",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1));f.store.addManagedDownload(1,series(),episode(1),target.getName());check(target.getName().equals(f.store.download(1).getString("downloadFile")),"filename bound at creation");f.delete(1);check(!target.exists(),"mapped file removed even when provider externally removed");}});
        group("corrupt zero-byte prepared mapping remains deletable",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1));Files.write(target.toPath(),new byte[0]);f.row(1,1,"preparedFile",target.getName());f.provider(1,null);check(LibraryStore.preparedFile(f.directory,f.store.download(1))==null,"fixture not playable");f.delete(1);check(!target.exists()&&f.store.download(1)==null,"corrupt owned prepared file deleted");}});
        group("missing file and missing provider record clean up",()->{try(Fixture f=new Fixture()){f.row(1,1,"preparedFile",uuid(1));f.delete(1);check(f.store.downloads().length()==0&&f.provider.removes==0,"missing mapped record removed");f.row(2,2,null,null);f.delete(2);check(f.store.downloads().length()==0,"failed or externally removed unmapped row removed");}});
        group("provider missing unmapped record never guesses files",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1));f.row(1,1,null,null);f.delete(1);check(target.exists(),"unbound file preserved");}});
        group("legacy prepared unique UUID with hidden URI recovers corrupt file",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1));f.row(1,1,null,null);f.provider.rows.put(1L,new DownloadDeletion.Record(null,"红果 · 已准备的视频"));f.delete(1);check(!target.exists(),"exact unique legacy file deleted");}});
        group("ambiguous legacy files rejected without side effects",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1)),second=f.file(uuid(1).replace("12345678-1234","aaaaaaaa-bbbb"));f.row(1,1,null,null);f.provider.rows.put(1L,new DownloadDeletion.Record(null,"红果 · 已准备的视频"));rejects(()->f.delete(1),"ambiguous UUID files guessed");check(target.exists()&&second.exists()&&f.provider.removes==0&&f.store.download(1)!=null,"ambiguous files and row preserved");}});
        group("exact legacy provider URI disambiguates multiple UUIDs",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1)),second=f.file(uuid(1).replace("12345678-1234","aaaaaaaa-bbbb"));f.row(1,1,null,null);f.provider.rows.put(1L,new DownloadDeletion.Record(target.toURI().toString(),"红果 · 已准备的视频"));f.delete(1);check(!target.exists()&&second.exists(),"only exact provider UUID deleted");}});
        group("foreign traversal symlink and directory paths rejected",()->{for(String kind:new String[]{"foreign","traversal","symlink","directory","badmapping"})try(Fixture f=new Fixture()){
            File target=f.file(uuid(1)),outside=new File(f.root,"outside.mp4");Files.write(outside.toPath(),new byte[]{7});
            f.row(1,1,"preparedFile",target.getName());
            if(kind.equals("foreign"))f.provider.rows.put(1L,new DownloadDeletion.Record(outside.toURI().toString(),"红果 · 已准备的视频"));
            if(kind.equals("traversal"))f.provider.rows.put(1L,new DownloadDeletion.Record("file:"+f.directory.getAbsolutePath()+"/../Download/"+target.getName(),"红果 · 已准备的视频"));
            if(kind.equals("symlink")){Files.delete(target.toPath());Files.createSymbolicLink(target.toPath(),outside.toPath());}
            if(kind.equals("directory")){Files.delete(target.toPath());check(target.mkdir(),"fixture directory");}
            if(kind.equals("badmapping")){JSONArray rows=f.store.downloads();rows.getJSONObject(0).put("preparedFile","../"+target.getName());f.context.prefs().edit().putString("downloads",rows.toString()).commit();}
            rejects(()->f.delete(1),"invalid path deleted");check(outside.exists()&&f.store.download(1)!=null&&f.provider.removes==0,"invalid target and provider untouched");
        }});
        group("symlink root rejected without following outside directory",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1)),link=new File(f.root,"linked-download");Files.createSymbolicLink(link.toPath(),f.directory.toPath());f.row(1,1,"preparedFile",target.getName());rejects(()->DownloadDeletion.delete(f.store,link,f.provider,params(1)),"symlink root accepted");check(target.exists()&&f.provider.removes==0,"symlink root target preserved");}});
        group("shared explicit mappings rejected",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1));f.row(1,1,"preparedFile",target.getName());f.row(2,1,"preparedFile",target.getName());rejects(()->f.delete(1),"shared mapped file deleted");check(target.exists()&&f.store.downloads().length()==2&&f.provider.removes==0,"shared file preserved");}});
        group("shared mapped and legacy provider file rejected",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1));f.row(1,1,"preparedFile",target.getName());f.row(2,1,null,null);f.provider(1,target);f.provider(2,target);rejects(()->f.delete(1),"legacy provider alias missed");check(target.exists()&&f.provider.removes==0,"provider alias preserved");}});
        group("provider query and remove failures preserve retry record",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1));f.row(1,1,null,null);f.provider(1,target);f.provider.failQuery=true;rejects(()->f.delete(1),"query failure hidden");check(!f.store.download(1).has("deleting")&&target.exists(),"query failed before destructive operations");f.provider.failQuery=false;f.provider.failRemove=true;rejects(()->f.delete(1),"remove failure hidden");check(f.store.download(1).has("deletingFile")&&target.exists(),"durable retry path saved");f.provider.failRemove=false;f.delete(1);check(!target.exists(),"remove failure retry completed");}});
        group("provider refusal does not report success",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1));f.row(1,1,null,null);f.provider(1,target);f.provider.keep=true;rejects(()->f.delete(1),"provider row remains but success returned");check(target.exists()&&f.store.download(1)!=null,"retained provider record is retryable");}});
        group("intent commit false and exception restore Android memory",()->{for(boolean throwing:new boolean[]{false,true})try(Fixture f=new Fixture()){File target=f.file(managed(1));f.row(1,1,null,null);f.provider(1,target);String before=f.store.downloads().toString();if(throwing)f.context.prefs().throwCommit=true;else f.context.prefs().failCommits=1;rejects(()->f.delete(1),"failed intent committed");check(target.exists()&&f.provider.removes==0&&before.equals(f.store.downloads().toString()),"failed intent does not delete and restores memory");check(before.equals(new LibraryStore(f.context.reopen()).downloads().toString()),"disk unchanged");f.delete(1);check(!target.exists(),"intent retry completes");}});
        group("failed restore commit still restores Android in-memory snapshot",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1));f.row(1,1,null,null);f.provider(1,target);String before=f.store.downloads().toString();f.context.prefs().failCommits=2;rejects(()->f.delete(1),"double disk failure hidden");check(before.equals(f.store.downloads().toString())&&target.exists()&&f.provider.removes==0,"memory restored although restore disk commit also fails");check(before.equals(new LibraryStore(f.context.reopen()).downloads().toString()),"unchanged original disk");}});
        group("file deletion failure retains exact durable retry target",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1));f.row(1,1,null,null);f.provider(1,target);rejects(()->DownloadDeletion.delete(f.store,f.directory,f.provider,params(1),file->{throw new IOException("fixture unlink denied");}),"file failure hidden");check(target.exists()&&f.store.download(1).has("deletingFile")&&f.provider.rows.isEmpty(),"provider removed but filename persisted");f.delete(1);check(!target.exists()&&f.store.download(1)==null,"file removal retry uses persisted target");}});
        group("final commit failure is explicit and retryable after irreversible removal",()->{try(Fixture f=new Fixture()){File target=f.file(managed(1));f.row(1,1,null,null);f.provider(1,target);f.provider.onRemove=()->f.context.prefs().failCommits=1;rejects(()->f.delete(1),"failed final metadata commit hidden");check(!target.exists()&&f.store.download(1)!=null&&f.store.download(1).has("deletingFile")&&!f.store.deletedDownload(1),"removed physical file not falsely restored or acknowledged");check(new LibraryStore(f.context.reopen()).download(1).has("deletingFile"),"disk retry target survives restart");f.provider.onRemove=null;f.delete(1);check(f.store.download(1)==null&&f.store.deletedDownload(1),"retry finishes metadata");}});
        group("repeat confirmed deletion is persisted idempotent no-op",()->{try(Fixture f=new Fixture()){f.row(1,1,null,null);f.delete(1);int queries=f.provider.queries;JSONObject second=DownloadDeletion.delete(new LibraryStore(f.context.reopen()),f.directory,f.provider,params(1));check(second.getBoolean("deleted")&&second.getBoolean("alreadyDeleted")&&f.provider.queries==queries,"tombstone retry no provider operation");rejects(()->f.delete(2),"tombstone authorizes other id");}});
        group("duplicate record identity rejected before deletion",()->{try(Fixture f=new Fixture()){File target=f.file(uuid(1));f.row(1,1,"preparedFile",target.getName());JSONArray rows=f.store.downloads();rows.getJSONObject(0).put("deleting",true);rows.put(new JSONObject(rows.getJSONObject(0).toString()));f.context.prefs().edit().putString("downloads",rows.toString()).commit();rejects(()->f.delete(1),"duplicate id accepted");check(target.exists()&&f.provider.queries==0,"duplicate identity did not reach provider");}});
        System.out.println("RESULT DownloadDeletion groups="+passed+" failed="+failed+" checks="+checks+" realFilesystem=true realLibraryStore=true injectedProvider=true networkRequests=0 deviceOperations=0");
        if(failed!=0)System.exit(1);
    }
}
